using System.Security.Cryptography;
using Microsoft.AspNetCore.Identity;
using MuzLoto.Web.Domain;

namespace MuzLoto.Web.Services;

/// <summary>
/// Customer accounts created by the booking form: the login is the phone number ("+79001234567"), the password is
/// generated by the site and shown to the customer once. The customer can change it in «Сменить пароль».
/// </summary>
public sealed class ClientAccounts(UserManager<AppUser> users)
{
    public sealed record Result(AppUser User, string? NewPassword);

    /// <summary>Finds the account of this phone, or creates one with a generated password (NewPassword is then set).</summary>
    public async Task<Result> FindOrCreateAsync(string phone, string name)
    {
        if (await FindByPhoneAsync(phone) is { } existing) return new(existing, null);
        var user = new AppUser { UserName = phone, PhoneNumber = phone, FullName = name, PrivacyConsentAt = DateTimeOffset.UtcNow };
        var password = GeneratePassword();
        var created = await users.CreateAsync(user, password);
        if (!created.Succeeded)
        {
            // Two submissions with the same new phone at once: the other one won, use its account.
            if (await FindByPhoneAsync(phone) is { } raced) return new(raced, null);
            throw new InvalidOperationException("Не удалось создать личный кабинет: " + string.Join("; ", created.Errors.Select(e => e.Code)));
        }
        await users.AddToRoleAsync(user, "User");
        return new(user, password);
    }

    public async Task<AppUser?> FindByPhoneAsync(string phone) =>
        ContactRules.NormalizePhone(phone) is { } normalized ? await users.FindByNameAsync(normalized) : null;

    /// <summary>Sets a new generated password (admin «Сбросить пароль»); existing sign-ins end.</summary>
    public async Task<string> ResetPasswordAsync(AppUser user)
    {
        var password = GeneratePassword();
        var token = await users.GeneratePasswordResetTokenAsync(user);
        var result = await users.ResetPasswordAsync(user, token, password);
        if (!result.Succeeded) throw new InvalidOperationException(string.Join("; ", result.Errors.Select(e => e.Code)));
        await users.UpdateSecurityStampAsync(user);
        return password;
    }

    /// <summary>Ten characters without look-alikes (no 0/O, 1/l/I), always with a digit — easy to retype from a screen.</summary>
    public static string GeneratePassword()
    {
        const string letters = "abcdefghjkmnpqrstuvwxyz", digits = "23456789", all = letters + digits;
        var chars = new char[10];
        for (var i = 0; i < chars.Length; i++) chars[i] = all[RandomNumberGenerator.GetInt32(all.Length)];
        chars[RandomNumberGenerator.GetInt32(chars.Length)] = digits[RandomNumberGenerator.GetInt32(digits.Length)];
        return new string(chars);
    }
}
